// Task 82: remove the FAKE sale of Y-VOLT Surge V (boss confirmation 2026-10-08).
// Boss: «regarding y-volt sale removal i meant this one: Y-VOLT Surge V /
// Молев Георгий Анатольевич / 27 сент. / 500 000 ₽ / Самовывоз / Продажа —
// please remove info about this particular sale from supabase»
//
// Scope (all info ABOUT this one sale):
//   1. private.sale_contract_artifacts  id=57258f91-4d3e-4cdb-9bf4-c7786478d007
//   2. public.cash_transactions         rows with sale_contract_id = that id
//   3. public.franchize_intents         sale intent generated by the doc flow
//   4. storage rental-contracts         vip-bike/sale-y-volt-surge-v-*.docx
// Audit block: crews.metadata.specs.owner_fix_20261008_sale_removal
// Run:  node --env-file=.env.local scripts/task82-remove-sale.mjs [--apply]
import { writeFileSync } from "node:fs";
import { createClient } from "/home/z/cartest/node_modules/@supabase/supabase-js/dist/main/index.js";

const APPLY = process.argv.includes("--apply");
const sb = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false } });
const ARTIFACT_ID = "57258f91-4d3e-4cdb-9bf4-c7786478d007";
const CREW_ID = "2d5fde70-1dd3-4f0d-8d72-66ccf6908746"; // vip-bike
const out = { mode: APPLY ? "APPLY" : "DRY-RUN", steps: [] };
const log = (s, v) => { out.steps.push({ s, v }); console.log(`${s}: ${JSON.stringify(v)?.slice(0, 300)}`); };

// 1. Artifact (re-confirm identity before touching anything)
const { data: art, error: artErr } = await sb.schema("private").from("sale_contract_artifacts").select("*").eq("id", ARTIFACT_ID).maybeSingle();
if (artErr) { console.error("artifact read err:", artErr.message); process.exit(1); }
if (!art || art.resolved_bike_id !== "y-volt-surge-v" || art.buyer_full_name !== "Молев Георгий Анатольевич" || String(art.sale_price) !== "500000") {
  console.error("ABORT: artifact identity mismatch", art && { bike: art.resolved_bike_id, buyer: art.buyer_full_name, price: art.sale_price });
  process.exit(1);
}
log("artifact confirmed", { id: art.id, key: art.contract_key, buyer: art.buyer_full_name, price: art.sale_price, created: art.created_at });

// 2. Money rows
const { data: cash, error: cashErr } = await sb.from("cash_transactions").select("id, transaction_type, amount, description, created_at").eq("sale_contract_id", ARTIFACT_ID);
if (cashErr) { console.error("cash read err:", cashErr.message); process.exit(1); }
log("cash rows linked to the sale", cash);

// 3. Intent row(s) — the sale intent created by the same doc flow (27.09, Молев, operator 413553377)
const { data: intents } = await sb.from("franchize_intents").select("id, intent_type, stage, created_at, metadata").eq("bike_id", "y-volt-surge-v").eq("intent_type", "sale").gte("created_at", "2026-09-27T16:00:00+00:00").lte("created_at", "2026-09-27T17:00:00+00:00");
const molIntent = (intents || []).filter((i) => i.metadata?.name === "Молев Георгий Анатольевич");
log("sale intents for the deal", molIntent);

// 4. Storage doc
const storagePath = art.storage_path;
const { data: stList } = await sb.storage.from("rental-contracts").list("vip-bike", { search: art.contract_key });
log("storage objects matching contract_key", (stList || []).map((o) => o.name));

if (!APPLY) {
  console.log("\nDRY-RUN complete — re-run with --apply to delete:", { artifact: ARTIFACT_ID, cash: cash?.map((c) => c.id), intents: molIntent.map((i) => i.id), storage: storagePath });
  writeFileSync("/home/z/cartest/scripts/task82-remove-out.json", JSON.stringify(out, null, 1));
  process.exit(0);
}

// ── APPLY ───────────────────────────────────────────────────────────────────
// Audit block FIRST (intent of action), then delete, then post-verify patch.
const auditKey = "owner_fix_20261008_sale_removal";
const { data: crewMetaRow } = await sb.from("crews").select("metadata").eq("id", CREW_ID).maybeSingle();
const meta = crewMetaRow?.metadata || {};
const specs = { ...(meta.specs || {}) };
specs[auditKey] = {
  at: new Date().toISOString(),
  by: "super-z (main agent) on boss explicit order in chat",
  boss_message: "regarding y-volt sale removal i meant this one: Y-VOLT Surge V / Молев Георгий Анатольевич / 27 сент. / 500 000 ₽ / Самовывоз / Продажа — please remove info about this particular sale from supabase",
  reason: "sale was fake (boss confirmation 2026-10-08)",
  artifact: { id: ARTIFACT_ID, contract_key: art.contract_key, buyer: art.buyer_full_name, sale_price: art.sale_price, created_at: art.created_at },
  cash_row_ids: (cash || []).map((c) => c.id),
  cash_amounts: (cash || []).map((c) => c.amount),
  intent_ids: molIntent.map((i) => i.id),
  storage_path: storagePath,
  status: "in_progress",
};
const { error: auditErr } = await sb.from("crews").update({ metadata: { ...meta, specs } }).eq("id", CREW_ID);
if (auditErr) { console.error("audit write err:", auditErr.message); process.exit(1); }
log("audit block written (in_progress)", auditKey);

// delete money rows first (FK-safe order), then artifact, then intent, then storage
for (const c of cash || []) {
  const { error } = await sb.from("cash_transactions").delete().eq("id", c.id);
  log(`cash delete ${c.id}`, error ? error.message : "ok");
}
const { error: artDelErr } = await sb.schema("private").from("sale_contract_artifacts").delete().eq("id", ARTIFACT_ID);
log("artifact delete", artDelErr ? artDelErr.message : "ok");
for (const i of molIntent) {
  const { error } = await sb.from("franchize_intents").delete().eq("id", i.id);
  log(`intent delete ${i.id}`, error ? error.message : "ok");
}
const { error: stErr } = await sb.storage.from("rental-contracts").remove([storagePath]);
log("storage remove", stErr ? stErr.message : "ok");

// post-verify
const { data: artAfter } = await sb.schema("private").from("sale_contract_artifacts").select("id").eq("id", ARTIFACT_ID).maybeSingle();
const { data: cashAfter } = await sb.from("cash_transactions").select("id").eq("sale_contract_id", ARTIFACT_ID);
const { data: intAfter } = await sb.from("franchize_intents").select("id").in("id", molIntent.map((i) => i.id).length ? molIntent.map((i) => i.id) : ["__none__"]);
const postOk = !artAfter && (cashAfter || []).length === 0 && (intAfter || []).length === 0;
log("post-verify", { artifactGone: !artAfter, cashGone: (cashAfter || []).length === 0, intentsGone: (intAfter || []).length === 0 });

specs[auditKey].status = postOk ? "applied_and_verified" : "applied_check_required";
specs[auditKey].verified_at = new Date().toISOString();
await sb.from("crews").update({ metadata: { ...meta, specs } }).eq("id", CREW_ID);
log("audit block finalized", specs[auditKey].status);
writeFileSync("/home/z/cartest/scripts/task82-remove-out.json", JSON.stringify(out, null, 1));
console.log(postOk ? "=== REMOVAL APPLIED & VERIFIED ===" : "=== CHECK REQUIRED ===");
